    url: string;
    state: string;
    headSha: string;
    mergeStateStatus: string;
    outcome: "passed" | "failed" | "pending";
    attempt: number;
    requestedAttempts: number;
    timeoutMs?: number;
    elapsedMs?: number;
    checks: { total: number; passed: number; failed: Names; pending: Names };
    note?: string;
    hint?: string;
